            IArtObjectGetter rhs,
            ArtObject.Mask<bool> ret,
            EqualsMaskHelper.Include include = EqualsMaskHelper.Include.All)
        {
            ret.EDID = string.Equals(item.EDID, rhs.EDID);
            ret.ObjectBounds = MaskItemExt.Factory(item.ObjectBounds.GetEqualsMask(rhs.ObjectBounds, include), include);
            ret.PreviewTransform = item.PreviewTransform.Equals(rhs.PreviewTransform);
            ret.XALG = MemorySliceExt.SequenceEqual(item.XALG, rhs.XALG);
            ret.FormTags = item.FormTags.CollectionEqualsHelper(
                rhs.FormTags,
                (l, r) => string.Equals(l, r),
                include);
            ret.ObjectPlacementDefaults = item.ObjectPlacementDefaults.CollectionEqualsHelper(
                rhs.ObjectPlacementDefaults,
                (loqLhs, loqRhs) => loqLhs.GetEqualsMask(loqRhs, include),
                include);
            ret.Keywords = item.Keywords.CollectionEqualsHelper(
                rhs.Keywords,
                (l, r) => object.Equals(l, r),
                include);
            ret.Model = EqualsMaskHelper.EqualsHelper(
                item.Model,
                rhs.Model,
                (loqLhs, loqRhs, incl) => loqLhs.GetEqualsMask(loqRhs, incl),
                include);
            ret.ENLM = MemorySliceExt.SequenceEqual(item.ENLM, rhs.ENLM);
            ret.ENLT = MemorySliceExt.SequenceEqual(item.ENLT, rhs.ENLT);
            ret.ENLS = item.ENLS.EqualsWithin(rhs.ENLS);
            ret.AUUV = MemorySliceExt.SequenceEqual(item.AUUV, rhs.AUUV);
